  ('de-lossd-si-ollas-von-ian-scheich-zoin-von-da-haundtoschn-bis-zum-ualaub', 'De lossd si ollas von ian Scheich zoin - von da Haundtoschn bis zum Ualaub!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die lässt sich alles von ihrem Scheich bezahlen – von der Handtasche bis zum Urlaub!', '[{"kategorie": "wörtlich", "text": "\"Die lässt sich doch alles von ihrem Sugardaddy bezahlen – von der Handtasche bis zum Urlaub!\"  2. Die lässt sich alles von ihrem Goldesel finanzieren – von Kopf bis Fuß!  3. Sie braucht keinen Job mehr – sie hat ja ihren Goldscheich auf Abruf!"}]'::jsonb, ''),
  ('solaung-da-scheich-zoid-san-mia-seine-soidoodn', 'Solaung da Scheich zoid, san mia seine Soidoodn!', '', '', '', 'Wiener Gaunersprache', 'Solange der Scheich zahlt, sind wir seine Soldaten!', '[{"kategorie": "wörtlich", "text": "\"Solange der schwerreiche Typ zahlt, tanzen wir nach seiner Pfeife!\"  2. Der Goldesel gibt den Takt vor - und wir marschieren im Gleichschritt mit!  3. Solange der Bonze die Kasse klingeln lässt, bellen wir auf sein Kommando!"}]'::jsonb, ''),
  ('warad-i-reich-wiara-scheich-warad-i-woaundas-und-ned-bei-eich', 'Warad I reich wiara Scheich, warad I woaundas und ned bei eich!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wäre ich reich wie ein Scheich, wäre ich woanders und nicht bei euch!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Wäre ich reich wie ein Scheich, säße ich woanders und nicht bei euch!\"  2. Wär ich reich und weltgewandt, säß'' ich nicht bei euch, sondern in einem fernen Land!  3. Wär ich reich wie ein Scheich, stünd hier statt mir nur noch ’ne Pflanze!"}]'::jsonb, ''),
  ('scheiss-di-nix-sunst-reisst-a-nix', 'Scheiss di nix, sunst reisst a nix!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Scheiß dich nichts, sonst reißt du nichts!', '[{"kategorie": "wörtlich", "text": "\"Trau dich was, sonst erreichst du nichts!\"  2. Kein Risiko, kein Erfolg!  3. Nur wer sich traut, wird Erfolg haben!"}]'::jsonb, 'Scheiss di nix!'),
  ('scheiss-di-nix', 'Scheiss di nix!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Scheiß dich nichts!', '[{"kategorie": "wörtlich", "text": "\"Lass dich nicht einschüchtern!\"  2. Mach dir nicht in die Hose!  3. So trau dich doch!  4. Fass dir ein Herz!  5. Nur Mut!"}]'::jsonb, ''),
  ('de-technik-is-a-hund', 'De Technik is a Hund!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Technik ist ein Hund!', '[{"kategorie": "wörtlich", "text": "\"Die Technik ist ein Biest!\"  2. Die Technik ist ganz schön tricky!\"  3. Die Technik ist eine echte Herausforderung!  4. Ständig hast du mit der Technik zu kämpfen!"}]'::jsonb, 'De Technik is a Hund -drei Stund fiara afochs Update!'),
  ('de-technik-is-a-hund-drei-stund-fiara-afochs-update', 'De Technik is a Hund -drei Stund fiara afochs Update!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Technik ist ein Hund - drei Stunden für ein Update!', '[{"kategorie": "wörtlich", "text": "\"Die Technik ist eine mühsame Angelegenheit - drei Stunden für ein einfaches Update!\"  2. Die Technik ist wieder einmal der Knackpunkt - drei Stunden für ein simples Update!  3. Die Technik ist ein [[Gfrett]] - drei Stunden für ein einfaches Update!"}]'::jsonb, 'De Technik is a Hund!'),
  ('schau-ma-moi', 'Schau ma moi!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Schau''n wir mal!', '[{"kategorie": "wörtlich", "text": "\"Mal schauen!\"  2. Wir werden sehen!  3. Erst mal locker bleiben!  4. Nichts überstürzen!  5. Lassen wir es auf uns zukommen!"}]'::jsonb, 'I waass no ned, ob I mitkumm - schau ma moi!'),
  ('i-waass-no-ned-ob-i-mitkumm-schau-ma-moi', 'I waass no ned, ob I mitkumm - schau ma moi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich weiß noch nicht, ob ich mitkomme - schauen wir mal!', '[{"kategorie": "wörtlich", "text": "\"Ich weiß noch nicht, ob ich mitkomme - mal schauen!\"  2. Ich weiß noch nicht, ob ich mitkomme - wir werden sehen!  3. Ich weiß noch nicht, ob ich mitkomme - ich lass das noch offen!"}]'::jsonb, 'Schau ma moi!'),
  ('des-is-kaa-hund', 'Des is kaa Hund!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist kein Hund!', '[{"kategorie": "wörtlich", "text": "\"Das ist nicht ohne!\"  2. Das ist nicht zu unterschätzen!  3. Das hat es in sich!  4. Das ist schwieriger als gedacht!  5. [[Des is ned schlaumpad!]]"}]'::jsonb, 'Da Aufschdiig zua Hittn - des is kaa Hund!'),
  ('da-aufschdiig-zua-hittn-des-is-kaa-hund', 'Da Aufschdiig zua Hittn - des is kaa Hund!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Aufstieg zur Hütte - das ist kein Hund!', '[{"kategorie": "wörtlich", "text": "\"Der Aufstieg zur Hütte - der ist nicht ohne!\"  2. Der Aufstieg zur Hütte - der hat es in sich!  3. Der Aufstieg zur Hütte - der ist nicht zu unterschätzen! (\""}]'::jsonb, ''),
  ('auf-wos-schdee-wia-da-hund-aufs-baa', 'auf wos schdee wia da Hund aufs Baa', '', '', '', 'Wiener Sprüche, die sitzen!', 'drauf stehen wie der Hund aufs Bein!', '[{"kategorie": "wörtlich", "text": "\"auf etwas stehen wie der Hund auf seinen Knochen\""}, {"kategorie": "", "text": "etwas ganz heiß lieben, scharf sein auf etwas"}, {"kategorie": "", "text": "brennen für etwas, Feuer und Flamme sein für etwas"}]'::jsonb, 'Dea schdeed auf des Mentsch wia da Hund aufs Baa!'),
  ('dea-schdeed-auf-des-mentsch-wia-da-hund-aufs-baa', 'Dea schdeed auf des Mentsch wia da Hund aufs Baa!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der steht auf das Mentsch wie der Hund aufs Bein!', '[{"kategorie": "wörtlich", "text": "\"Der steht auf das Mädchen wie der Hund auf seinen Knochen!\"  2. Der hat voll einen Narren an dem Mädchen gefressen!  3. Der ist Hals über Kopf in das Mädchen verliebt!"}]'::jsonb, 'auf wos schdee wia da Hund aufs Baa'),
